<template>
  <div class="home-container">
    <div class="recognition-card">
      <h2>Сервіс Розпізнавання (CIFAR-3)</h2>
      <p>Оберіть зображення для обробки нейронною мережею на Raspberry Pi.</p>

      <div class="input-group">
        <label for="image-upload" class="file-label">Виберіть файл</label>
        <input 
          type="file" 
          @change="handleFileChange" 
          id="image-upload" 
          accept="image/*"
          :disabled="isProcessing"
        >
        <span class="file-name">{{ selectedFile ? selectedFile.name : 'Файл не обрано' }}</span>
      </div>

      <div class="image-area">
        <img v-if="imagePreviewUrl" :src="imagePreviewUrl" alt="Preview" class="image-preview" />
        <div v-else class="placeholder">Зображення 32x32</div>
      </div>
      
      <button 
        @click="recognizeImage" 
        :disabled="!selectedFile || isProcessing"
        :class="{ 'processing': isProcessing }"
      >
        <span v-if="isProcessing">Обробка...</span>
        <span v-else>Розпізнати зображення</span>
      </button>

      <div class="result-box" :class="{ 'pending': isProcessing, 'error': predictionResult.startsWith('❌') }">
        <strong>Статус:</strong> {{ predictionResult }}
        <div v-if="taskId" class="task-id">ID Завдання: {{ taskId }}</div>
      </div>
    </div>
  </div>
</template>


<script>
import { ref, push, onValue, set, getDatabase } from "firebase/database"; 

export default {
    name: 'ImageRecognition',
    data() {
        return {
            // Конфігурація нейронки
            TARGET_SIZE: 32,
            CHANNELS: 3,

            // Стан
            selectedFile: null,
            imagePreviewUrl: null,
            taskId: null,
            predictionResult: 'Очікування завантаження зображення...',
            isProcessing: false,
        };
    },
    computed: {
        // Унікальний шлях до завдання в Firebase
        taskPath() {
            return this.taskId ? `image_tasks/${this.taskId}` : null;
        }
    },
    methods: {
        // 1. Обробка вибору файлу користувачем
        handleFileChange(event) {
            this.selectedFile = event.target.files[0];
            if (this.selectedFile) {
                this.imagePreviewUrl = URL.createObjectURL(this.selectedFile);
                this.predictionResult = 'Натисніть "Розпізнати", щоб відправити на обробку.';
            } else {
                this.imagePreviewUrl = null;
            }
        },

        // 2. Попередня обробка зображення та перетворення на масив
        async preprocessImage() {
            if (!this.selectedFile) {
                alert("Будь ласка, виберіть зображення!");
                return;
            }

            this.predictionResult = 'Перетворення зображення...';

            return new Promise((resolve, reject) => {
                const img = new Image();
                img.src = this.imagePreviewUrl;
                img.onload = () => {
                    const canvas = document.createElement('canvas');
                    const ctx = canvas.getContext('2d');
                    
                    // Встановлюємо розмір Canvas для обрізки
                    canvas.width = this.TARGET_SIZE;
                    canvas.height = this.TARGET_SIZE;
                    
                    // Обрізка та зміна розміру: малюємо зображення на Canvas 32x32.
                    // Це автоматично змінить розмір зображення.
                    ctx.drawImage(img, 0, 0, this.TARGET_SIZE, this.TARGET_SIZE);

                    // Отримання даних пікселів (RGBA)
                    const imageData = ctx.getImageData(0, 0, this.TARGET_SIZE, this.TARGET_SIZE);
                    const data = imageData.data; // Uint8ClampedArray: [R, G, B, A, R, G, B, A, ...]

                    // Перетворення даних на одновимірний масив [0.0, 1.0] (R1, G1, B1, R2, G2, B2, ...)
                    // та ігнорування альфа-каналу (A)
                    const imageArray = [];
                    for (let i = 0; i < data.length; i += 4) {
                        // Нормалізація: ділимо значення пікселів (0-255) на 255.0
                        imageArray.push(data[i] / 255.0);   // R
                        imageArray.push(data[i + 1] / 255.0); // G
                        imageArray.push(data[i + 2] / 255.0); // B
                        // Ігноруємо data[i + 3] (Alpha)
                    }


                    // Перевірка кінцевого розміру масиву
                    if (imageArray.length === this.TARGET_SIZE * this.TARGET_SIZE * this.CHANNELS) {
                        resolve(imageArray);
                    } else {
                        reject(new Error("Помилка формування масиву. Некоректний розмір."));
                    }
                };
                img.onerror = () => reject(new Error("Помилка завантаження зображення."));
            });
        },
        
        // 3. Відправка завдання до Firebase
        async sendTaskToFirebase(imageArray) {
            this.predictionResult = 'Відправка завдання до Raspberry Pi...';
            this.isProcessing = true;

            const db = getDatabase(); 
            
            const tasksRef = ref(db, 'image_tasks');
            
            // Створення нового завдання з унікальним ID
            const newTaskRef = push(tasksRef);
            this.taskId = newTaskRef.key;
            
            const jsonString = JSON.stringify(imageArray);
            const base64String = btoa(jsonString);
            
            const imgDataRef = ref(db, `image_data/${this.taskId}`);
            await set(imgDataRef, { 
                data: base64String 
            }); 
            
            const taskData = {
                status: 'pending',
                date: new Date().toISOString(),
            };
            
            await set(newTaskRef, taskData);
            
            this.predictionResult = `Завдання ${this.taskId} відправлено. Очікування відповіді...`;
            this.listenForResponse();
        },

        // 4. Очікування відповіді від Raspberry Pi
        listenForResponse() {
            if (!this.taskPath) return;

            // ⚡️ ВИПРАВЛЕННЯ: Отримуємо DB тут
            const db = getDatabase();

            const taskRef = ref(db, this.taskPath);
            
            // Встановлюємо слухача на вузол
            onValue(taskRef, (snapshot) => {
                const data = snapshot.val();
                if (data && data.status === 'completed' && data.answer) {
                    
                    this.predictionResult = `Відповідь: ${data.answer.toUpperCase()}`;
                    this.isProcessing = false;
                
                } else if (data && data.status === 'processing') {
                    this.predictionResult = '⏳ Raspberry Pi обробляє завдання...';
                }
            }, {
                onlyOnce: false 
            });
        },

        // 5. Головна функція, яка запускає процес
        async recognizeImage() {
            if (this.isProcessing) return;
            
            try {
                // Очищаємо попередній стан
                this.taskId = null;
                this.isProcessing = true;
                this.predictionResult = 'Старт обробки...';

                // 1. Попередня обробка
                const imageArray = await this.preprocessImage();
                
                // 2. Відправка в Firebase та запуск слухача
                await this.sendTaskToFirebase(imageArray);
                
            } catch (error) {
                console.error("Помилка розпізнавання:", error);
                // Включаємо перевірку на внутрішній баг Firebase, хоча ми його обійшли.
                if (error.message.includes('newChildren.insert')) {
                    this.predictionResult = `Помилка: Внутрішній конфлікт даних. Спробуйте оновити сторінку.`;
                } else {
                    this.predictionResult = `Помилка: ${error.message}`;
                }
                this.isProcessing = false;
            }
        }
    }
};
</script>

<style lang="less" scoped>
  @import "../assets/css/ImageRecognition.css";
</style>